// F76: testar scripts/nyhetskoll.cjs mot en egen liten sajt i os.tmpdir() och en gång mot repots nytt.json.
// Rör inga filer i repot och tar bort testsajten efteråt.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const skript = path.resolve('scripts', 'nyhetskoll.cjs');
const krav = {};
krav.skriptetFinns = fs.existsSync(skript);
const kod = krav.skriptetFinns ? fs.readFileSync(skript, 'utf8') : '';
const utan = kod.split('\n').filter((r) => !r.trim().startsWith('//')).join('\n');
const kravda = [...utan.matchAll(/require\('([^']+)'\)/g)].map((m) => m[1]);
krav.baraFsOchPath = kravda.length > 0 && kravda.every((m) => m === 'fs' || m === 'path');
krav.skriverInget = !/(writeFile|appendFile|unlink|rmSync|rmdir|mkdir|renameSync|copyFile|createWriteStream)/.test(utan) && !/https?:/.test(utan);
krav.aiMarkt = kod.includes('AI-skapat') && kod.includes('Generated by AI, Directed by MS');

const rot = fs.mkdtempSync(path.join(os.tmpdir(), 'nyhetskoll-test-'));
const pub = path.join(rot, 'public');
const skriv = (f, t) => { fs.mkdirSync(path.dirname(path.join(pub, f)), { recursive: true }); fs.writeFileSync(path.join(pub, f), t); };
const kor = (...a) => { const r = spawnSync(process.execPath, [skript, ...a], { encoding: 'utf8' }); let j = null; try { j = JSON.parse(r.stdout.trim().split('\n').pop()); } catch (e) {} return { kod: r.status, j }; };
const titlar = (l) => (l || []).map((p) => p.titel);
try {
  for (const f of ['index.html', 'a.html', 'b.html', 'c.html', '404.html', 'nyhetsbrev.html', 'band/index.html']) skriv(f, '<!doctype html>');
  const poster = [
    { datum: '2026-11-07', titel: 'A', status: 'forhandsgranskning', lank: '/a' },
    { datum: '2026-11-06', titel: 'Vy', status: 'forhandsgranskning', lank: '/#vy' },
    { datum: '2026-11-05', titel: 'Band', status: 'forhandsgranskning', lank: '/band' },
    { datum: '2026-11-04', titel: 'Extern', status: 'forhandsgranskning', lank: 'https://exempel.invalid/' },
    { datum: '2026-11-03', titel: 'B live', status: 'live', lank: '/b.html' },
    { datum: '2026-11-02', titel: 'Utan', status: 'forhandsgranskning' },
    { datum: '2026-11-01', titel: 'Pagar', status: 'pagar', lank: null },
  ];
  const nytt = JSON.stringify({ uppdaterad: '2026-11-07', poster }, null, 2);
  skriv('data/nytt.json', nytt);
  if (krav.skriptetFinns) {
    const r = kor('--rot', rot);
    krav.kandidaterRatt = r.kod === 0 && JSON.stringify(titlar(r.j && r.j.kandidaterLive)) === '["A","Vy","Band"]';
    krav.utanLankRatt = JSON.stringify(titlar(r.j && r.j.utanLank)) === '["Utan"]';
    krav.sidorUtanPostRatt = !!r.j && JSON.stringify(r.j.sidorUtanPost) === '["c.html"]';
    krav.ingenBrutenNuOk = !!r.j && r.j.brutna.length === 0 && r.j.ok === true;
    krav.inteAndrat = fs.readFileSync(path.join(pub, 'data', 'nytt.json'), 'utf8') === nytt;
    skriv('data/nytt.json', JSON.stringify({ poster: [...poster, { datum: '2026-11-08', titel: 'Bruten', status: 'live', lank: '/finns-inte' }] }));
    const b = kor('--rot', rot);
    krav.brutenLankRod = b.kod === 1 && b.j && b.j.ok === false && JSON.stringify(titlar(b.j.brutna)) === '["Bruten"]';
    krav.felAnrop = kor('--okand').kod === 2 && kor('--rot').kod === 2 && kor('--rot', path.join(rot, 'saknas')).kod === 2;
    const riktig = kor('--rot', process.cwd());
    krav.riktigaRepot = (riktig.kod === 0 || riktig.kod === 1) && !!riktig.j && typeof riktig.j.poster === 'number';
  }
} finally {
  fs.rmSync(rot, { recursive: true, force: true });
}

for (const k of ['kandidaterRatt', 'utanLankRatt', 'sidorUtanPostRatt', 'ingenBrutenNuOk', 'brutenLankRod', 'felAnrop', 'inteAndrat', 'riktigaRepot']) if (!(k in krav)) krav[k] = false;
const ok = Object.values(krav).every(Boolean);
if (!ok) console.error('Röda: ' + Object.keys(krav).filter((k) => !krav[k]).join(', '));
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
